#include <stdexcept>

class RiskLimit {
public:
    explicit RiskLimit(double max) : max_(max) {
        if (max_ < 0) throw std::invalid_argument("limit cannot be negative");
    }
    void set(double max) {
        if (max < 0) throw std::invalid_argument("limit cannot be negative");
        max_ = max;
    }
    double max() const { return max_; }
    bool allows(double exposure) const {
        return exposure <= max_ && exposure >= -max_;
    }
private:
    double max_;
};

