#include <stdexcept>
#include <string>

class Money {
public:
    Money(long long pence, const std::string& ccy) : pence_(pence), ccy_(ccy) {}
    long long pence() const { return pence_; }
    std::string ccy() const { return ccy_; }
private:
    long long pence_;
    std::string ccy_;
};

Money operator+(const Money& a, const Money& b) {
    if (a.ccy() != b.ccy()) throw std::invalid_argument("currencies differ");
    return Money(a.pence() + b.pence(), a.ccy());
}

bool operator==(const Money& a, const Money& b) {
    return a.pence() == b.pence() && a.ccy() == b.ccy();
}

