#include <algorithm>
#include <vector>

template <typename T>
std::vector<T> top_n(std::vector<T> xs, int n) {
    std::sort(xs.begin(), xs.end());
    std::reverse(xs.begin(), xs.end());
    if (n < static_cast<int>(xs.size())) xs.resize(n);
    return xs;
}
